            smallest = s.charAt(i);
        }
        if (largest == -1 || s.charAt(i) > largest) {
            largest = s.charAt(i);
        }
    }
    while (result.length() < n) {
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == smallest && result.indexOf(c) == -1) {
                result += c;
                smallest++;
                break;
            }
        }
        for (int i = n-1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == largest && result.indexOf(c) == -1) {
                result += c;
                largest--;
                break;
            }
        }
    }
    return result;
}
