public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();

    for (int i = low; i <= high; i++) {
        if (isSteppingNumber(i)) {
            steppingNumbers.add(i);
        }
    }

    Collections.sort(steppingNumbers);
    return steppingNumbers;
}

private static boolean isSteppingNumber(int n) {
    if (n == 0) {
        return true;
    }

    String numStr = String.valueOf(n);
    int lastDigit = numStr.charAt(numStr.length() - 1) - '0';
    int nextDigit = numStr.charAt(numStr.length() - 2) - '0';

    if (nextDigit == lastDigit && lastDigit == 0) {
        return false;
    }

    return Math.abs(nextDigit - lastDigit) == 1;
}

