public static int squarePermutations(int[] A) {
    int size = A.length;
    int[] B = new int[size];
    for (int i = 0; i < size; i++) {
        B[i] = A[i];
    }
    Arrays.sort(B);
    boolean[] visited = new boolean[size];
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (!visited[i]) {
            count++;
            int j = i + 1;
            while (j < size && B[i] + B[j] * B[j] == B[j]) {
                visited[j] = true;
                j++;
            }
            if (j == size) {
                break;
            }
            i = j - 1;
        }
    }
    return count;
}
