public static int[] diagonalOrder(int[][] mat) {
    // Check if the input matrix is valid
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[] {};
    }

    // Initialize the result array with the same size as the matrix
    int[] result = new int[mat.length * mat[0].length];

    // Loop through each diagonal starting from the main diagonal
    for (int i = 0; i < mat.length; i++) {
        // Calculate the starting and ending indices of the current diagonal
        int startIdx = i, endIdx = mat[0].length - i - 1;
        if (startIdx < 0) {
            startIdx = 0;
        }
        if (endIdx < 0) {
            endIdx = mat[0].length - 1;
        }

        // Loop through the current diagonal and add the elements to the result array
        for (int j = startIdx; j <= endIdx; j++) {
            result[i + j - startIdx] = mat[i][j];
        }
    }

    return result;
}
