public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        if (!contains(nums, num)) {
            sum += num;
        }
    }
    return sum;
}

private static boolean contains(int[] nums, int num) {
    for (int n : nums) {
        if (n == num) {
            return true;
        }
    }
